const USES = {"ua/read-syllables":["russian"],"ru/read-syllables":["russian"],"ru/read-potter":["russian","potter"],"ua/read-potter":["russian","potter"],"ru/riddles":["russian"],"ua/riddles":["russian"],"ua/english-words":["english"],"ru/english-words":["english"],"ua/english-pictures":["english"],"ru/english-pictures":["english"],"ru/english-phrases-ru":["english-phrases"],"ua/english-phrases-ru":["english-phrases"],"ua/english-phrases-en":["english-phrases"],"ru/english-phrases-en":["english-phrases"],"ua/english-phrases-assemble":["english-phrases"],"ru/english-phrases-assemble":["english-phrases"],"ru/english-tenses-listen":["english-tenses"],"ua/english-tenses-listen":["english-tenses"],"ru/english-tenses-say":["english-tenses"],"ua/english-tenses-say":["english-tenses"]}; // lesson ("ru/read-syllables") -> shared folders it loads files from
const LANGS = ["ru","ua"]; // language folders: each holds a home page and the lessons in that language
// The site shares its origin (school-lessons.github.io) with the other sites of the organization, so its caches
// carry its own prefix and only they are ever deleted
const PREFIX = "primary";
const CACHE = PREFIX;
const FONTS = `${PREFIX}-fonts`;
const ROOT = new URL("./", self.location.href);

// Site path of a URL: "read-syllables/" → "read-syllables/index.html"; null outside the site
function sitePath(url) {
  if (url.origin !== ROOT.origin || !url.pathname.startsWith(ROOT.pathname)) return null;
  let path;
  try {
    path = decodeURIComponent(url.pathname.slice(ROOT.pathname.length));
  } catch {
    return null;
  }
  return path === "" || path.endsWith("/") ? path + "index.html" : path;
}

const known = (path) => path !== null && Object.hasOwn(FILES, path);
const cacheKey = (path) => `${new URL(path, ROOT).href}?v=${FILES[path]}`;

// Folder a file belongs to: "ru/read-syllables" for a lesson file, "english" for a shared folder,
// or null for a home page and the other files of the site root and of a language folder
function lessonOf(path) {
  const parts = path.split("/");
  const depth = LANGS.includes(parts[0]) ? 2 : 1;
  return parts.length > depth ? parts.slice(0, depth).join("/") : null;
}
const lessonFiles = (lesson) =>
  [lesson, ...(USES[lesson] ?? [])].flatMap((dir) => Object.keys(FILES).filter((path) => path.startsWith(dir + "/")));

// Downloads the files that are not in the cache yet (in their current version)
async function precache(paths) {
  const cache = await caches.open(CACHE);
  const have = new Set((await cache.keys()).map((request) => request.url));
  const results = await Promise.allSettled(
    paths
      .filter((path) => !have.has(cacheKey(path)))
      .map(async (path) => {
        const response = await fetch(new URL(path, ROOT), { cache: "no-cache" });
        if (!response.ok) throw new Error(`${path}: ${response.status}`);
        await cache.put(cacheKey(path), response);
      }),
  );
  const failed = results.filter((r) => r.status === "rejected");
  if (failed.length) throw new Error(`Not cached: ${failed.length} of ${results.length}`);
}

// Lessons that already have something in the cache (they were opened before)
async function cachedLessons() {
  const cache = await caches.open(CACHE);
  const lessons = new Set();
  for (const request of await cache.keys()) {
    const lesson = lessonOf(sitePath(new URL(request.url)) ?? "");
    if (lesson && lessonFiles(lesson).length) lessons.add(lesson);
    // Lessons used to live at the site root, now that address only redirects to ru/<lesson>/
    if (lesson && !lesson.includes("/") && lessonFiles(`ru/${lesson}`).length) lessons.add(`ru/${lesson}`);
  }
  return [...lessons];
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      await precache(Object.keys(FILES).filter((path) => lessonOf(path) === null));
      // Lessons that were available offline stay complete after the update
      await Promise.allSettled((await cachedLessons()).map((lesson) => precache(lessonFiles(lesson))));
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      for (const name of await caches.keys()) {
        if (name.startsWith(PREFIX) && name !== CACHE && name !== FONTS) await caches.delete(name);
      }
      const wanted = new Set(Object.keys(FILES).map(cacheKey));
      const cache = await caches.open(CACHE);
      for (const request of await cache.keys()) {
        if (!wanted.has(request.url)) await cache.delete(request);
      }
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.hostname === "fonts.googleapis.com" || url.hostname === "fonts.gstatic.com") {
    event.respondWith(fromFontCache(url.href));
    return;
  }
  const path = sitePath(url);
  if (!known(path)) return;
  event.respondWith(fromCache(request, path));
  const lesson = lessonOf(path);
  if (request.mode === "navigate" && lesson) event.waitUntil(precache(lessonFiles(lesson)).catch(() => {}));
});

async function fromCache(request, path) {
  const cache = await caches.open(CACHE);
  let response = await cache.match(cacheKey(path));
  if (!response) {
    response = await fetch(new URL(path, ROOT), { cache: "no-cache" });
    if (response.ok) await cache.put(cacheKey(path), response.clone());
  }
  const range = request.headers.get("range");
  return range && response.ok ? sliceRange(response, range) : response;
}

// <audio> asks for byte ranges; Safari will not play a file from the cache without a 206 answer
async function sliceRange(response, range) {
  const blob = await response.blob();
  const size = blob.size;
  const match = /^bytes=(\d*)-(\d*)$/.exec(range.trim());
  let start = NaN;
  let end = NaN;
  if (match && match[1] !== "") {
    start = Number(match[1]);
    end = match[2] === "" ? size - 1 : Math.min(Number(match[2]), size - 1);
  } else if (match && match[2] !== "") {
    start = Math.max(0, size - Number(match[2])); // "bytes=-500": the last 500 bytes
    end = size - 1;
  }
  if (!(start <= end)) return new Response(null, { status: 416, headers: { "Content-Range": `bytes */${size}` } });
  return new Response(blob.slice(start, end + 1), {
    status: 206,
    headers: {
      "Content-Type": response.headers.get("Content-Type") ?? "application/octet-stream",
      "Content-Range": `bytes ${start}-${end}/${size}`,
      "Content-Length": String(end - start + 1),
      "Accept-Ranges": "bytes",
    },
  });
}

// The font CSS is requested without CORS; fetch it with CORS so the cached copy is not opaque
async function fromFontCache(url) {
  const cache = await caches.open(FONTS);
  const cached = await cache.match(url);
  if (cached) return cached;
  const response = await fetch(url, { mode: "cors" });
  if (response.ok) await cache.put(url, response.clone());
  return response;
}
